style.css:
@-moz-document domain("google.com") {
/* Background */
body {
  background: url("https://wallpapercave.com/wp/wp8984722.jpg") no-repeat center center fixed !important;
  background-size: cover !important;
}

/* Main search area */
#search, .main {
  background: rgba(255, 255, 255, 0.75) !important;
  backdrop-filter: blur(10px) !important;
  border-radius: 20px !important;
  padding: 20px !important;
}

/* Search bar */
textarea, input[name="q"] {
  background: rgba(255,255,255,0.8) !important;
  border-radius: 25px !important;
  border: none !important;
  padding: 10px !important;
  color: #3a4a5a !important;
}

/* Buttons */
input[type="submit"], .gNO89b, .RNmpXc {
  background: #aee1ff !important;
  border: none !important;
  border-radius: 20px !important;
  color: #2f3e4d !important;
}

/* Search results */
.g, .tF2Cxc {
  background: rgba(255,255,255,0.7) !important;
  border-radius: 15px !important;
  padding: 10px !important;
  margin-bottom: 10px !important;
}

/* Links */
a {
  color: #5aaed6 !important;
}

/* Top bar */
#hdtb, #appbar {
  background: rgba(255,255,255,0.6) !important;
  backdrop-filter: blur(10px) !important;
}

/* Remove dark overlays */
html {
  background: transparent !important;
}
}
